  'abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about';

/** HU-06-02, mnemonic de prueba canónico de Hardhat/Anvil (passphrase vacía). */
const MNEMONIC_HARDHAT = 'test test test test test test test test test test test junk';
50→
/** HU-06-02, tabla de known-answer tests `address_index` → dirección EIP-55. */
const DIRECCIONES_HARDHAT: readonly string[] = [
  '0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266',
  '0x70997970C51812dc3A010C7d01b50e0d17dc79C8',
